        roles: List[str],
        primary_role: str,
        is_active: bool = True,
        is_admin_approved: bool = False,
        is_verified: bool = False,
    ):
        self.id = id
        self.email = email
        self.full_name = full_name
        self.role = role
        self.roles = roles
        self.primary_role = primary_role
        self.is_active = is_active
        self.is_admin_approved = is_admin_approved
        self.is_verified = is_verified

    def has_role(self, role: str) -> bool:
        return role in self.roles

    def has_any_role(self, roles: List[str]) -> bool:
        return bool(set(self.roles) & set(roles))

    @property
    def is_admin(self) -> bool:
        return self.has_any_role(["super_admin", "admin"])

    @property
    def is_doctor(self) -> bool:
        return self.has_role("doctor")

    @property
    def is_patient(self) -> bool:
        return self.has_any_role(["patient", "client"])

    @property
    def is_hospital(self) -> bool:
        return self.has_any_role(["hospital", "hospital_admin"])

    @property
    def is_pharmacy(self) -> bool:
        return self.has_any_role(["pharmacy", "pharmacy_admin"])

    @property
    def is_blood_donor(self) -> bool:
