def require_role(*allowed_roles: str):
    """
    FastAPI dependency that enforces role-based access control.
    Usage: @router.get("/", dependencies=[Depends(require_role("admin", "super_admin"))])
    """
    async def role_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_active:
            raise ForbiddenException("Account is deactivated")
        if not current_user.has_any_role(list(allowed_roles)):
            raise ForbiddenException(
                f"Access denied. Required role: {', '.join(allowed_roles)}"
            )
        return current_user

    return role_checker


def require_admin():
    """Shortcut for admin-only endpoints."""
    return require_role("super_admin", "admin")


def require_doctor():
    """Shortcut for doctor-only endpoints."""
    return require_role("doctor")


def require_patient():
    """Shortcut for patient/client endpoints."""
    return require_role("patient", "client")


def require_hospital():
    """Shortcut for hospital endpoints."""
    return require_role("hospital", "hospital_admin")


def require_pharmacy():
    """Shortcut for pharmacy endpoints."""
    return require_role("pharmacy", "pharmacy_admin")


def require_verified():
    """
    Dependency that requires the user to be verified.
    Can be combined with require_role using multiple dependencies.
    """
    async def verification_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_verified:
            raise ForbiddenException("Email verification required")
        return current_user

    return verification_checker


def require_approved():
    """
    Dependency that requires the user to be admin-approved.
    Used for doctors, hospitals, pharmacies who need approval.
    """
    async def approval_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_admin_approved:
            raise ForbiddenException("Admin approval required")
        return current_user

    return approval_checker

# app2/middleware/auth.py - JWT Authentication & Role-Based Access
import jwt
import bcrypt
import uuid
from datetime import datetime, timedelta
from functools import wraps
from flask import request, jsonify
from ..config import Config
from ..database import DB

def hash_password(password):
    return bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt(10)).decode('utf-8')

def check_password(password, hashed):
    return bcrypt.checkpw(password.encode('utf-8'), hashed.encode('utf-8'))

def generate_uuid():
    return str(uuid.uuid4())

def generate_token(user_id, role):
    payload = {
        'user_id': user_id,
        'role': role,
        'exp': datetime.utcnow() + timedelta(hours=Config.JWT_ACCESS_EXPIRY_HOURS),
        'iat': datetime.utcnow()
    }
    return jwt.encode(payload, Config.JWT_SECRET, algorithm=Config.JWT_ALGORITHM)

def decode_token(token):
    return jwt.decode(token, Config.JWT_SECRET, algorithms=[Config.JWT_ALGORITHM])

def jwt_token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            return jsonify({'error': 'Token required'}), 401
        try:
            data = decode_token(token)
            user = DB.fetch_one("SELECT * FROM users WHERE id = %s", (data['user_id'],))
            if not user:
                return jsonify({'error': 'User not found'}), 401
            request.user = user
            request.user_role = data.get('role', 'patient')
        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token expired'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Invalid token'}), 401
        return f(*args, **kwargs)
    return decorated

def role_required(*roles):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if not hasattr(request, 'user_role'):
                return jsonify({'error': 'Not authenticated'}), 401
            if request.user_role not in roles and request.user_role != 'admin':
                return jsonify({'error': 'Access denied'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

from fastapi import HTTPException, Request
from fastapi.responses import JSONResponse
from fastapi.exceptions import RequestValidationError
from typing import Optional, Any, Dict
import logging

logger = logging.getLogger("aetherion.exceptions")


# ============================================
# EXCEPTION CLASSES
# ============================================

class AppException(HTTPException):
    """Base application exception."""

    def __init__(
        self,
        message: str = "An error occurred",
        status_code: int = 400,
        details: Optional[Any] = None,
    ):
        super().__init__(status_code=status_code, detail=message)
        self.message = message
        self.details = details


class NotFoundException(AppException):
    def __init__(self, message: str = "Resource not found"):
        super().__init__(message=message, status_code=404)


class UnauthorizedException(AppException):
    def __init__(self, message: str = "Unauthorized access"):
        super().__init__(message=message, status_code=401)


class ForbiddenException(AppException):
    def __init__(self, message: str = "You do not have permission to perform this action"):
        super().__init__(message=message, status_code=403)


class ConflictException(AppException):
    def __init__(self, message: str = "Resource already exists"):
        super().__init__(message=message, status_code=409)


class BadRequestException(AppException):
    def __init__(self, message: str = "Bad request", details: Optional[Any] = None):
        super().__init__(message=message, status_code=400, details=details)


class ValidationException(AppException):
    def __init__(self, message: str = "Validation error", details: Optional[Any] = None):
        super().__init__(message=message, status_code=422, details=details)


class RateLimitException(AppException):
    def __init__(self, message: str = "Too many requests. Please try again later."):
        super().__init__(message=message, status_code=429)


class InternalServerException(AppException):
    def __init__(self, message: str = "Internal server error"):
        super().__init__(message=message, status_code=500)


class ServiceUnavailableException(AppException):
    def __init__(self, message: str = "Service temporarily unavailable"):
        super().__init__(message=message, status_code=503)


# ============================================
# GLOBAL EXCEPTION HANDLERS
# ============================================

async def app_exception_handler(request: Request, exc: AppException) -> JSONResponse:
    """Handle all AppException subclasses with consistent JSON format."""
    request_id = getattr(request.state, "request_id", "unknown")

    response_body = {
        "success": False,
        "message": exc.message,
        "error": {
            "type": exc.__class__.__name__,
            "status_code": exc.status_code,
            "request_id": request_id,
        },
    }

    if exc.details:
        response_body["error"]["details"] = exc.details

    return JSONResponse(
        status_code=exc.status_code,
        content=response_body,
    )


async def validation_exception_handler(request: Request, exc: RequestValidationError) -> JSONResponse:
    """Handle Pydantic/FastAPI validation errors with structured details."""
    request_id = getattr(request.state, "request_id", "unknown")

    errors = []
    for error in exc.errors():
        errors.append({
            "field": ".".join(str(loc) for loc in error.get("loc", [])),
            "message": error.get("msg", "Validation error"),
            "type": error.get("type", "value_error"),
        })

    return JSONResponse(
        status_code=422,
        content={
            "success": False,
            "message": "Validation error",
            "error": {
                "type": "ValidationError",
                "status_code": 422,
                "request_id": request_id,
                "details": errors,
            },
        },
    )


async def unhandled_exception_handler(request: Request, exc: Exception) -> JSONResponse:
    """Catch-all handler for unhandled exceptions — returns 500 with correlation ID."""
    import uuid
    request_id = getattr(request.state, "request_id", str(uuid.uuid4()))

    logger.error(
        f"Unhandled exception on {request.method} {request.url.path}: {exc}",
        extra={"request_id": request_id},
        exc_info=True,
    )

    return JSONResponse(
        status_code=500,
        content={
            "success": False,
            "message": "An unexpected error occurred",
            "error": {
                "type": "InternalServerError",
                "status_code": 500,
                "request_id": request_id,
            },
        },
    )


# ============================================
# EXCEPTION HANDLERS REGISTRY
# ============================================

def get_exception_handlers() -> Dict:
    """
    Returns a dict of exception handlers to register with FastAPI.
    Usage:
        for exc_class, handler in get_exception_handlers().items():
            app.add_exception_handler(exc_class, handler)
    """
    return {
        AppException: app_exception_handler,
        RequestValidationError: validation_exception_handler,
        Exception: unhandled_exception_handler,
    }

