from ..models.appointment import Appointment
from ..models.emergency import EmergencyRequest
from ..models.search import AuditLog, SecurityLog
from ..models.review import Feedback
from ..schemas.admin import (
    VerificationRequestResponse, VerificationActionRequest,
    AdminDashboardResponse, AuditLogResponse,
    FeedbackResponse, FeedbackResolveRequest,
)
from ..core.exceptions import NotFoundException, BadRequestException, ForbiddenException
from ..utils.helpers import build_pagination_meta


class AdminService:
    def __init__(self, db: Session):
        self.db = db

    def get_dashboard(self) -> AdminDashboardResponse:
        total_users = self.db.query(User).count()
        total_doctors = self.db.query(DoctorProfile).count()
        total_hospitals = self.db.query(Hospital).count()
        total_pharmacies = self.db.query(Pharmacy).count()
        total_appointments = self.db.query(Appointment).count()
        pending_verifs = self.db.query(VerificationRequest).filter(
            VerificationRequest.status == "pending"
        ).count()
        active_emergencies = self.db.query(EmergencyRequest).filter(
            EmergencyRequest.status.in_(["pending", "dispatched", "en-route"])
        ).count()
        recent_signups = self.db.query(User).filter(
            User.created_at >= datetime.utcnow() - timedelta(days=7)
        ).count()

        return AdminDashboardResponse(
            total_users=total_users,
            total_doctors=total_doctors,
            total_hospitals=total_hospitals,
            total_pharmacies=total_pharmacies,
            total_appointments=total_appointments,
            pending_verifications=pending_verifs,
            active_emergencies=active_emergencies,
            recent_signups=recent_signups,
        )

    def get_verifications(self, status: Optional[str] = None, page: int = 1, size: int = 20) -> dict:
        query = self.db.query(VerificationRequest)
        if status:
            query = query.filter(VerificationRequest.status == status)
        query = query.order_by(VerificationRequest.created_at.desc())
        total = query.count()
        items = query.offset((page - 1) * size).limit(size).all()
        return {
            "items": [VerificationRequestResponse.model_validate(v) for v in items],
            **build_pagination_meta(total, page, size),
        }

    def process_verification(self, verification_id: str, admin_user_id: str, data: VerificationActionRequest) -> VerificationRequestResponse:
        vreq = self.db.query(VerificationRequest).filter(VerificationRequest.id == verification_id).first()
        if not vreq:
            raise NotFoundException("Verification request not found")

        valid_statuses = ["approved", "rejected", "more-info"]
        if data.status not in valid_statuses:
            raise BadRequestException(f"Invalid status. Must be one of: {valid_statuses}")

        vreq.status = data.status
        vreq.reviewed_by = admin_user_id
        if data.rejection_reason:
            vreq.rejection_reason = data.rejection_reason
        if data.notes:
            vreq.notes = data.notes

        # Update the entity's verification status
        if data.status == "approved":
            if vreq.entity_type == "doctor":
                profile = self.db.query(DoctorProfile).filter(DoctorProfile.id == vreq.entity_id).first()
                if profile:
                    profile.is_verified = True
            elif vreq.entity_type == "hospital":
                hospital = self.db.query(Hospital).filter(Hospital.id == vreq.entity_id).first()
                if hospital:
                    hospital.is_verified = True
            elif vreq.entity_type == "pharmacy":
                pharmacy = self.db.query(Pharmacy).filter(Pharmacy.id == vreq.entity_id).first()
                if pharmacy:
                    pharmacy.is_verified = True

        self.db.commit()
        self.db.refresh(vreq)
        return VerificationRequestResponse.model_validate(vreq)

    def get_audit_logs(self, page: int = 1, size: int = 20, user_id: Optional[str] = None, action: Optional[str] = None) -> dict:
        query = self.db.query(AuditLog)
        if user_id:
            query = query.filter(AuditLog.user_id == user_id)
        if action:
            query = query.filter(AuditLog.action.ilike(f"%{action}%"))
        query = query.order_by(AuditLog.created_at.desc())
        total = query.count()
        logs = query.offset((page - 1) * size).limit(size).all()
        return {
            "items": [AuditLogResponse.model_validate(l) for l in logs],
            **build_pagination_meta(total, page, size),
        }

    def get_feedback(self, status: Optional[str] = None, page: int = 1, size: int = 20) -> dict:
        query = self.db.query(Feedback)
        if status:
            query = query.filter(Feedback.status == status)
        query = query.order_by(Feedback.created_at.desc())
        total = query.count()
        items = query.offset((page - 1) * size).limit(size).all()
        return {
            "items": [FeedbackResponse.model_validate(f) for f in items],
            **build_pagination_meta(total, page, size),
        }

    def resolve_feedback(self, feedback_id: str, admin_user_id: str, data: FeedbackResolveRequest) -> FeedbackResponse:
        fb = self.db.query(Feedback).filter(Feedback.id == feedback_id).first()
        if not fb:
            raise NotFoundException("Feedback not found")
        fb.status = data.status
        fb.response = data.response
        fb.resolved_by = admin_user_id
        self.db.commit()
        self.db.refresh(fb)
        return FeedbackResponse.model_validate(fb)

    def toggle_user_active(self, user_id: str, is_active: bool) -> dict:
        user = self.db.query(User).filter(User.id == user_id).first()
        if not user:
            raise NotFoundException("User not found")
        user.is_active = is_active
        self.db.commit()
        return {"user_id": user_id, "is_active": is_active}

    def get_users(self, page: int = 1, size: int = 20, search: Optional[str] = None, role: Optional[str] = None, status: Optional[str] = None) -> dict:
        query = (
            self.db.query(User)
            .join(UserRole, User.id == UserRole.user_id, isouter=True)
            .join(Role, UserRole.role_id == Role.id, isouter=True)
        )

        if search:
            query = query.filter(
                (User.full_name.ilike(f"%{search}%")) |
                (User.email.ilike(f"%{search}%")) |
                (User.phone.ilike(f"%{search}%"))
            )

        if role:
            role_obj = self.db.query(Role).filter(Role.name == role).first()
            if role_obj:
                query = query.filter(User.primary_role_id == role_obj.id)

        if status == "active":
            query = query.filter(User.is_active == True)
        elif status == "blocked":
            query = query.filter(User.is_active == False)
        elif status == "verified":
            query = query.filter(User.is_verified == True)
        elif status == "pending":
            query = query.filter(User.is_verified == False, User.is_active == True)

        query = query.order_by(User.created_at.desc())
        total = query.count()
        users = query.offset((page - 1) * size).limit(size).all()

        items = []
        for u in users:
            user_role = self.db.query(Role).filter(Role.id == u.primary_role_id).first()
            items.append({
                "id": u.id,
                "full_name": u.full_name,
                "email": u.email,
                "phone": u.phone,
                "role": user_role.name if user_role else "unknown",
                "role_display": user_role.display_name if user_role else "Unknown",
                "status": "active" if u.is_active else "blocked",
                "is_verified": u.is_verified,
                "is_admin_approved": u.is_admin_approved,
                "gender": u.gender,
                "blood_group": u.blood_group,
                "is_online": u.is_online,
                "created_at": u.created_at.isoformat() if u.created_at else None,
                "last_login_at": u.last_login_at.isoformat() if u.last_login_at else None,
            })

        return {
            "items": items,
            **build_pagination_meta(total, page, size),
        }

    def get_system_stats(self) -> dict:
        from ..models.blood_donation import BloodDonor, BloodRequest
        from ..models.oxygen import OxygenRequest as OxyReq
        return {
            "users": self.db.query(User).count(),
            "doctors": self.db.query(DoctorProfile).count(),
            "hospitals": self.db.query(Hospital).count(),
            "pharmacies": self.db.query(Pharmacy).count(),
            "appointments": self.db.query(Appointment).count(),
            "blood_donors": self.db.query(BloodDonor).count(),
            "blood_requests": self.db.query(BloodRequest).count(),
            "oxygen_requests": self.db.query(OxyReq).count(),
            "emergencies": self.db.query(EmergencyRequest).count(),
        }

from datetime import datetime, timedelta
from typing import Optional, Dict, Any, Tuple
from jose import JWTError, jwt
from passlib.context import CryptContext

from .config import get_settings

settings = get_settings()

pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")


# ============================================
# PASSWORD HASHING
# ============================================

def hash_password(password: str) -> str:
    return pwd_context.hash(password)


def verify_password(plain_password: str, hashed_password: str) -> bool:
    return pwd_context.verify(plain_password, hashed_password)


# ============================================
# JWT TOKEN CREATION
# ============================================

def create_access_token(data: Dict[str, Any], expires_delta: Optional[timedelta] = None) -> str:
    to_encode = data.copy()
    expire = datetime.utcnow() + (expires_delta or timedelta(minutes=settings.ACCESS_TOKEN_EXPIRE_MINUTES))
    to_encode.update({"exp": expire, "type": "access"})
    return jwt.encode(to_encode, settings.JWT_SECRET_KEY, algorithm=settings.JWT_ALGORITHM)


def create_refresh_token(data: Dict[str, Any], expires_delta: Optional[timedelta] = None) -> str:
    to_encode = data.copy()
    expire = datetime.utcnow() + (expires_delta or timedelta(days=settings.REFRESH_TOKEN_EXPIRE_DAYS))
    to_encode.update({"exp": expire, "type": "refresh"})
    return jwt.encode(to_encode, settings.JWT_SECRET_KEY, algorithm=settings.JWT_ALGORITHM)


def create_token_pair(data: Dict[str, Any]) -> Tuple[str, str]:
    """Create an access token and refresh token pair together."""
    access_token = create_access_token(data)
    refresh_token = create_refresh_token({"sub": data.get("sub")})
    return access_token, refresh_token


# ============================================
# JWT TOKEN DECODING & VALIDATION
# ============================================

def decode_token(token: str) -> Optional[Dict[str, Any]]:
    """Decode a JWT token. Returns None if invalid/expired."""
    try:
        return jwt.decode(token, settings.JWT_SECRET_KEY, algorithms=[settings.JWT_ALGORITHM])
    except JWTError:
        return None


def decode_and_validate_token(token: str, expected_type: str = "access") -> Optional[Dict[str, Any]]:
    """Decode and strictly validate a JWT token with type and expiry checks."""
    payload = decode_token(token)
    if not payload:
        return None

    if payload.get("type") != expected_type:
        return None

    # Check expiry explicitly (jose handles this, but double-check)
    exp = payload.get("exp")
    if exp and datetime.utcnow() > datetime.utcfromtimestamp(exp):
        return None

    return payload


# ============================================
# TOKEN ROTATION
# ============================================

def rotate_refresh_token(old_refresh_token: str, user_data: Dict[str, Any]) -> Optional[Tuple[str, str]]:
    """
    Validate an existing refresh token and issue a new token pair.
    Returns (new_access_token, new_refresh_token) or None if invalid.
    The caller is responsible for revoking the old session in the database.
    """
    payload = decode_and_validate_token(old_refresh_token, expected_type="refresh")
    if not payload:
        return None

    # Verify user_id matches
    old_sub = payload.get("sub")
    if not old_sub or old_sub != user_data.get("sub"):
        return None

    return create_token_pair(user_data)

from fastapi import Depends, HTTPException
from typing import List, Optional
from ..middleware.auth_middleware import get_current_user
from ..core.exceptions import ForbiddenException


class CurrentUser:
    """Represents the authenticated user injected into requests."""

    def __init__(
        self,
        id: str,
        email: str,
        full_name: str,
        role: str,
        roles: List[str],
        primary_role: str,
        is_active: bool = True,
        is_admin_approved: bool = False,
        is_verified: bool = False,
    ):
        self.id = id
        self.email = email
        self.full_name = full_name
        self.role = role
        self.roles = roles
        self.primary_role = primary_role
        self.is_active = is_active
        self.is_admin_approved = is_admin_approved
        self.is_verified = is_verified

    def has_role(self, role: str) -> bool:
        return role in self.roles

    def has_any_role(self, roles: List[str]) -> bool:
        return bool(set(self.roles) & set(roles))

    @property
    def is_admin(self) -> bool:
        return self.has_any_role(["super_admin", "admin"])

    @property
    def is_doctor(self) -> bool:
        return self.has_role("doctor")

    @property
    def is_patient(self) -> bool:
        return self.has_any_role(["patient", "client"])

    @property
    def is_hospital(self) -> bool:
        return self.has_any_role(["hospital", "hospital_admin"])

    @property
    def is_pharmacy(self) -> bool:
        return self.has_any_role(["pharmacy", "pharmacy_admin"])

    @property
    def is_blood_donor(self) -> bool:
        return self.has_role("blood_donor")


def require_role(*allowed_roles: str):
    """
    FastAPI dependency that enforces role-based access control.
    Usage: @router.get("/", dependencies=[Depends(require_role("admin", "super_admin"))])
    """
    async def role_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_active:
            raise ForbiddenException("Account is deactivated")
        if not current_user.has_any_role(list(allowed_roles)):
            raise ForbiddenException(
                f"Access denied. Required role: {', '.join(allowed_roles)}"
            )
        return current_user

    return role_checker


def require_admin():
    """Shortcut for admin-only endpoints."""
    return require_role("super_admin", "admin")


def require_doctor():
    """Shortcut for doctor-only endpoints."""
    return require_role("doctor")


def require_patient():
    """Shortcut for patient/client endpoints."""
    return require_role("patient", "client")


def require_hospital():
    """Shortcut for hospital endpoints."""
    return require_role("hospital", "hospital_admin")


def require_pharmacy():
    """Shortcut for pharmacy endpoints."""
    return require_role("pharmacy", "pharmacy_admin")


def require_verified():
    """
    Dependency that requires the user to be verified.
    Can be combined with require_role using multiple dependencies.
    """
    async def verification_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_verified:
            raise ForbiddenException("Email verification required")
        return current_user

    return verification_checker


def require_approved():
    """
    Dependency that requires the user to be admin-approved.
    Used for doctors, hospitals, pharmacies who need approval.
    """
    async def approval_checker(current_user: CurrentUser = Depends(get_current_user)) -> CurrentUser:
        if not current_user.is_admin_approved:
            raise ForbiddenException("Admin approval required")
        return current_user

    return approval_checker

# app2/middleware/auth.py - JWT Authentication & Role-Based Access
import jwt
import bcrypt
import uuid
from datetime import datetime, timedelta
from functools import wraps
from flask import request, jsonify
from ..config import Config
from ..database import DB

def hash_password(password):
    return bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt(10)).decode('utf-8')

def check_password(password, hashed):
    return bcrypt.checkpw(password.encode('utf-8'), hashed.encode('utf-8'))

def generate_uuid():
    return str(uuid.uuid4())

def generate_token(user_id, role):
    payload = {
        'user_id': user_id,
        'role': role,
        'exp': datetime.utcnow() + timedelta(hours=Config.JWT_ACCESS_EXPIRY_HOURS),
        'iat': datetime.utcnow()
    }
    return jwt.encode(payload, Config.JWT_SECRET, algorithm=Config.JWT_ALGORITHM)

def decode_token(token):
    return jwt.decode(token, Config.JWT_SECRET, algorithms=[Config.JWT_ALGORITHM])

def jwt_token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            return jsonify({'error': 'Token required'}), 401
        try:
            data = decode_token(token)
            user = DB.fetch_one("SELECT * FROM users WHERE id = %s", (data['user_id'],))
            if not user:
                return jsonify({'error': 'User not found'}), 401
            request.user = user
            request.user_role = data.get('role', 'patient')
        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token expired'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Invalid token'}), 401
        return f(*args, **kwargs)
    return decorated

def role_required(*roles):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if not hasattr(request, 'user_role'):
                return jsonify({'error': 'Not authenticated'}), 401
            if request.user_role not in roles and request.user_role != 'admin':
                return jsonify({'error': 'Access denied'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

from fastapi import HTTPException, Request
from fastapi.responses import JSONResponse
from fastapi.exceptions import RequestValidationError
from typing import Optional, Any, Dict
import logging

logger = logging.getLogger("aetherion.exceptions")


# ============================================
# EXCEPTION CLASSES
# ============================================

class AppException(HTTPException):
    """Base application exception."""

    def __init__(
        self,
        message: str = "An error occurred",
        status_code: int = 400,
        details: Optional[Any] = None,
    ):
        super().__init__(status_code=status_code, detail=message)
        self.message = message
        self.details = details


class NotFoundException(AppException):
    def __init__(self, message: str = "Resource not found"):
        super().__init__(message=message, status_code=404)


class UnauthorizedException(AppException):
    def __init__(self, message: str = "Unauthorized access"):
        super().__init__(message=message, status_code=401)


class ForbiddenException(AppException):
    def __init__(self, message: str = "You do not have permission to perform this action"):
        super().__init__(message=message, status_code=403)


class ConflictException(AppException):
    def __init__(self, message: str = "Resource already exists"):
        super().__init__(message=message, status_code=409)


class BadRequestException(AppException):
    def __init__(self, message: str = "Bad request", details: Optional[Any] = None):
        super().__init__(message=message, status_code=400, details=details)


class ValidationException(AppException):
    def __init__(self, message: str = "Validation error", details: Optional[Any] = None):
        super().__init__(message=message, status_code=422, details=details)


class RateLimitException(AppException):
    def __init__(self, message: str = "Too many requests. Please try again later."):
        super().__init__(message=message, status_code=429)


class InternalServerException(AppException):
    def __init__(self, message: str = "Internal server error"):
        super().__init__(message=message, status_code=500)


class ServiceUnavailableException(AppException):
    def __init__(self, message: str = "Service temporarily unavailable"):
        super().__init__(message=message, status_code=503)


# ============================================
# GLOBAL EXCEPTION HANDLERS
# ============================================

async def app_exception_handler(request: Request, exc: AppException) -> JSONResponse:
    """Handle all AppException subclasses with consistent JSON format."""
    request_id = getattr(request.state, "request_id", "unknown")

    response_body = {
        "success": False,
        "message": exc.message,
        "error": {
            "type": exc.__class__.__name__,
            "status_code": exc.status_code,
            "request_id": request_id,
        },
    }

    if exc.details:
        response_body["error"]["details"] = exc.details

    return JSONResponse(
        status_code=exc.status_code,
        content=response_body,
    )


async def validation_exception_handler(request: Request, exc: RequestValidationError) -> JSONResponse:
    """Handle Pydantic/FastAPI validation errors with structured details."""
    request_id = getattr(request.state, "request_id", "unknown")

    errors = []
    for error in exc.errors():
        errors.append({
            "field": ".".join(str(loc) for loc in error.get("loc", [])),
            "message": error.get("msg", "Validation error"),
            "type": error.get("type", "value_error"),
        })

    return JSONResponse(
        status_code=422,
        content={
            "success": False,
            "message": "Validation error",
            "error": {
                "type": "ValidationError",
                "status_code": 422,
                "request_id": request_id,
                "details": errors,
            },
        },
    )


async def unhandled_exception_handler(request: Request, exc: Exception) -> JSONResponse:
    """Catch-all handler for unhandled exceptions — returns 500 with correlation ID."""
    import uuid
    request_id = getattr(request.state, "request_id", str(uuid.uuid4()))

    logger.error(
        f"Unhandled exception on {request.method} {request.url.path}: {exc}",
        extra={"request_id": request_id},
        exc_info=True,
    )

    return JSONResponse(
        status_code=500,
        content={
            "success": False,
            "message": "An unexpected error occurred",
            "error": {
                "type": "InternalServerError",
                "status_code": 500,
                "request_id": request_id,
            },
        },
    )


# ============================================
# EXCEPTION HANDLERS REGISTRY
# ============================================

def get_exception_handlers() -> Dict:
    """
    Returns a dict of exception handlers to register with FastAPI.
    Usage:
        for exc_class, handler in get_exception_handlers().items():
            app.add_exception_handler(exc_class, handler)
    """
    return {
        AppException: app_exception_handler,
        RequestValidationError: validation_exception_handler,
        Exception: unhandled_exception_handler,
    }

from typing import Optional
import uuid
from math import ceil


def generate_uuid() -> str:
    return str(uuid.uuid4())


def paginate(page: int = 1, size: int = 20) -> dict:
    return {"offset": (page - 1) * size, "limit": size}


def calculate_pages(total: int, size: int) -> int:
    """Calculate total number of pages."""
    if size <= 0:
        return 0
    return ceil(total / size)


def build_pagination_meta(total: int, page: int, size: int) -> dict:
    """Build pagination metadata for API responses."""
    return {
        "total": total,
        "page": page,
        "size": size,
        "pages": calculate_pages(total, size),
    }


def generate_order_number(prefix: str = "ORD") -> str:
    """Generate a unique order number."""
    import time
    return f"{prefix}-{int(time.time())}-{uuid.uuid4().hex[:6].upper()}"


def generate_request_number(prefix: str = "REQ") -> str:
    """Generate a unique request number."""
    import time
    return f"{prefix}-{int(time.time())}-{uuid.uuid4().hex[:6].upper()}"

# app2/routes/auth.py - Authentication Routes (Register/Login/Password)
from flask import Blueprint, request, jsonify
from ..database import DB
from ..middleware.auth import hash_password, check_password, generate_uuid, generate_token

auth_bp = Blueprint('auth', __name__)

@auth_bp.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    required = ['email', 'password', 'full_name', 'role']
    for field in required:
        if field not in data:
            return jsonify({'error': f'{field} is required'}), 400

    if DB.fetch_one("SELECT id FROM users WHERE email = %s", (data['email'],)):
        return jsonify({'error': 'Email already registered'}), 409

    role = DB.fetch_one("SELECT id FROM roles WHERE name = %s", (data['role'],))
    if not role:
        return jsonify({'error': 'Invalid role'}), 400

    user_id = generate_uuid()
    pw_hash = hash_password(data['password'])

    DB.execute(
        """INSERT INTO users (id, email, phone, password_hash, full_name, gender,
        date_of_birth, primary_role_id, is_verified, is_active) 
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
        (user_id, data['email'], data.get('phone', ''), pw_hash,
         data['full_name'], data.get('gender'), data.get('date_of_birth'),
         role['id'], True, True))

    DB.execute("INSERT INTO user_roles (user_id, role_id, is_primary) VALUES (%s,%s,%s)",
               (user_id, role['id'], True))

    token = generate_token(user_id, data['role'])
    return jsonify({
        'message': 'Registration successful',
        'token': token,
        'user': {
            'id': user_id, 'email': data['email'], 'full_name': data['full_name'],
            'role': data['role'], 'is_authenticated': True,
            'roles': [data['role']], 'primary_role': data['role']
        }
    }), 201

@auth_bp.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or not data.get('email') or not data.get('password'):
        return jsonify({'error': 'Email and password required'}), 400

    user = DB.fetch_one("SELECT * FROM users WHERE email = %s AND is_active = TRUE", (data['email'],))
    if not user:
        return jsonify({'error': 'Invalid credentials'}), 401

    if not check_password(data['password'], user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    if data.get('role'):
        role_name = data['role']
    else:
        role_row = DB.fetch_one(
            "SELECT r.name FROM roles r JOIN user_roles ur ON r.id = ur.role_id WHERE ur.user_id = %s AND ur.is_primary = TRUE",
            (user['id'],))
        role_name = role_row['name'] if role_row else 'patient'

    DB.execute("UPDATE users SET last_login_at = NOW() WHERE id = %s", (user['id'],))

    token = generate_token(user['id'], role_name)
    return jsonify({
        'message': 'Login successful',
        'token': token,
        'user': {
            'id': user['id'], 'email': user['email'], 'full_name': user['full_name'],
            'role': role_name, 'is_authenticated': True,
            'roles': [role_name], 'primary_role': role_name
        }
    })

@auth_bp.route('/refresh', methods=['POST'])
def refresh():
    return jsonify({'message': 'Use login to refresh token'})

@auth_bp.route('/forgot-password', methods=['POST'])
def forgot_password():
    data = request.get_json()
    user = DB.fetch_one("SELECT id FROM users WHERE email = %s", (data.get('email', ''),))
    if user:
        token = generate_uuid()
        DB.execute("INSERT INTO password_resets (email, token, expires_at) VALUES (%s, %s, DATE_ADD(NOW(), INTERVAL 1 HOUR))",
                   (data['email'], token))
        return jsonify({'message': 'Reset link sent', 'reset_token': token})
    return jsonify({'error': 'Email not found'}), 404

@auth_bp.route('/reset-password', methods=['POST'])
def reset_password():
    data = request.get_json()
    reset = DB.fetch_one("SELECT * FROM password_resets WHERE token = %s AND is_used = FALSE AND expires_at > NOW()",
                         (data.get('token', ''),))
    if reset:
        pw_hash = hash_password(data['password'])
        DB.execute("UPDATE users SET password_hash = %s WHERE email = %s", (pw_hash, reset['email']))
        DB.execute("UPDATE password_resets SET is_used = TRUE WHERE token = %s", (data['token'],))
        return jsonify({'message': 'Password reset successful'})
    return jsonify({'error': 'Invalid or expired token'}), 400

